# -*- coding: utf-8 -*-
"""Türkçe metin işleme fonksiyonları."""

_TR_LOWER_MAP = {
    'I': 'ı',  # U+0130 LATIN CAPITAL LETTER I -> dotless i
    'İ': 'i',  # U+0130 dotted capital I -> i
}

_TR_UPPER_MAP = {
    'i': 'İ',   # only the ASCII 'i' becomes dotted İ in Turkish
    'ı': 'I',   # dotless i -> I
}


def tr_lower(s):
    """Türkçe kurallarıyla küçük harfe çevirir."""
    out = []
    for ch in s:
        if ch in _TR_LOWER_MAP:
            out.append(_TR_LOWER_MAP[ch])
        elif 'A' <= ch <= 'Z':
            out.append(chr(ord(ch) + 32))
        else:
            out.append(ch)
    return ''.join(out)


def tr_upper(s):
    """Türkçe kurallarıyla büyük harfe çevirir."""
    out = []
    for ch in s:
        if ch in _TR_UPPER_MAP:
            out.append(_TR_UPPER_MAP[ch])
        elif 'a' <= ch <= 'z':
            out.append(chr(ord(ch) - 32))
        else:
            out.append(ch)
    return ''.join(out)


_TR_ALPHABET = "abcçdefgğhıijklmnoöpqrsştuüvwxyz"
_ORDER = {ch: i for i, ch in enumerate(_TR_ALPHABET)}


def _tr_sort_key(word):
    """Sıralama anahtarı: (karakter sırası listesi)."""
    key = []
    for ch in word:
        low = tr_lower(ch)
        if low in _ORDER:
            key.append((0, 0, _ORDER[low]))  # listedeki harfler: alfabetik sıra
        else:
            key.append((1, ord(ch), 0))      # diğerler: önce kod noktasına göre
    return key


def tr_sorted(words):
    """Kelimeleri Türk alfabesine göre, büyük/küçük farkı gözetmeden sıralar.

    Kararsız sıralama yerine (indeks) eklenerek eşit kelimelerin girdideki
    sırası korunur; girdi listesi değiştirilmez."""
    return [w for _, w in sorted(enumerate(words), key=lambda t: (_tr_sort_key(t[1]), t[0]))]

